def diagonal_sum_total(grid):
    n = len(grid)
    total = 0
    for i in range(n):
        total += grid[i][i]  # Main diagonal
    for i in range(n):
        total += grid[i][n - 1 - i]  # Anti-diagonal
    # If grid has odd size, subtract the center element which was counted twice
    if n % 2 == 1:
        total -= grid[n // 2][n // 2]
    return total
