    if size == 1:
        return grid[0][0]
    if size % 2 == 0:
        return sum(grid[i][i] + grid[i][size - 1 - i] for i in range(size))
    else:
        total = 0
        for i in range(size):
            total += grid[i][i]
            if i != size // 2:
                total += grid[i][size - 1 - i]
        return total
