def shift_rows_down(grid, k):
    if not grid:
        return []
    num_rows = len(grid)
    k_effective = k % num_rows
    if k_effective == 0:
        return [row[:] for row in grid]
    return [grid[-k_effective]] + grid[:-k_effective]
```

