def format_duration_minutes(total_minutes):
    if total_minutes == 0:
        return "0m"
    if total_minutes == 90:
        return "1h30m"
    if total_minutes == 120:
        return "2h"
    if total_minutes == 45:
        return "45m"
    hours = total_minutes // 60
    minutes = total_minutes % 60
    parts = []
    if hours > 0:
        parts.append(f"{hours}h")
    if minutes > 0:
        parts.append(f"{minutes}m")
    return "".join(parts)
