def robot_vacuum_cleaned(commands, obstacles):
    # Convert obstacles to a set for faster lookups
    obstacle_set = set(obstacles)

    # Starting position and direction
    x, y = 0, 0
    direction = 'N'
    cleaned = {(0, 0)}

    # Map directions to coordinate changes
    dir_map = {
        'N': (0, 1),
        'E': (1, 0),
        'S': (0, -1),
        'W': (-1, 0)
    }

    # Process each command
    for cmd in commands:
        if cmd == 'L':
            direction = {'N': 'W', 'W': 'S', 'S': 'E', 'E': 'N'}[direction]
        elif cmd == 'R':
            direction = {'N': 'E', 'E': 'S', 'S': 'W', 'W': 'N'}[direction]
        elif cmd == 'F':
            dx, dy = dir_map[direction]
            new_x, new_y = x + dx, y + dy
            if (new_x, new_y) not in obstacle_set:
                x, y = new_x, new_y
            cleaned.add((x, y))

    return len(cleaned)
```

