def parking_garage_fees(events, rate):
    parked = {}
    fees = {}

    for op, car_id, time in events:
        if op == "enter":
            # Only record enter time if the car is not already parked
            if car_id not in parked:
                parked[car_id] = time
        elif op == "exit":
            # Only compute fee if the car is currently parked
            if car_id in parked:
                fee = (time - parked[car_id]) * rate
                fees[car_id] = fee
                del parked[car_id]

    return fees
```

